    import heapq
    extract_from_input = lambda: int(base_input())

    flown_flights_by_airport = [0] * (n + 1)
    airports_for_flights_by_flight_id = [[] for _ in range(m)]
    frontier = []
    for flight in flights:
        transports = min(flown_flights_by_airport[flight[0]] + flight[2], flown_flights_by_airport[flight[1]] + 1 - flight[2])
        flown_flights_by_airport[flight[1]] += 1
        airports_for_flights_by_flight_id[flight[2] - 1].append(flight[1])

    for flight_index, new_airport in enumerate(airports_for_flights_by_flight_id[0]):
        heapq.heappush(frontier, (new_airport, 0, 1))

    found_end = False
    flights_to_city = 0

    while not found_end:
        current_city, current_flight_index, new_flown_flights = heapq.heappop(frontier)

        if current_city == n:
            found_end = True

        else:
            for next_airport in airports_for_flights_by_flight_id[current_flight_index]:
                remaining_flown_flights = flown_flights_by_airport[next_airport] + new_flown_flights - flight_index

                if not remaining_flown_flights: 
                    continue

                if remaining_flown_flights < new_flown_flights: 
                    flown_flights_by_airport[next_airport] = new_flown_flights
                    heapq.heappush(frontier, (next_airport, current_flight_index, remaining_flown_flights))

    return str(flights_to_city + (1 if not found_end else 1))

