from collections import deque

def solve(n, k, a):
    lengths = [1] * n  # Lengths of greedy subsequences for each element in a subsegment.
    prev = [-1] * n  # Predecessor indices for elements in the subsegment.
    queue = deque()
    for i in range(k - 1, -1, -1):
        t = 0
        for j in range(i, n, k):
            if a[j] < lengths[t]:
                t = a[j] + 1
        if t == k:
            t = 0
        queue.append((i, a[i] + 1))
        lengths[i] = queue[0][1]
        while queue and queue[0][1] < a[queue[0][0]]:
            queue.popleft()
        prev[i] = queue[0][0]
    for j in range(k, n):
        index = prev[j]
        while queue and queue[0][1] > a[index + 1] + 1:
            queue.popleft()
        if queue:
            queue[0][1] = a[index + 1] + 1
    queue.clear()
    for i in range(k):
        index = prev[k - i - 1]
        t = 1
        for j in range(index, k):
            if a[j] <= lengths[t]:
                t = a[j] + 1
        if t == k:
            t = 0
        queue.append((k - i - 1, a[k - i - 1] + 1))
        length = queue[0][1] + 1
        prev[k - i - 1] = next((p[0] for p in queue if p[1] == length and p[1] <= a[index + 1]), 0)
    prev.reverse()
    for i, l in enumerate(prev, k):
        lengths[i % (k - 1)] = max(lengths[(i % (k - 1)) + (prev[i % (k - 1)] + 1) % (k - 1)], lengths[i % (k - 1)])
    return lengths

