from collections import deque
from typing import List

def min_operations(image_colors: List[int], n: int) -> int:
    rows, cols = len(image_colors), len(image_colors[0])
    queue = deque([(0, 0, 0)])  # (row, col, color)
    directions = [(1, 0), (0, 1)]  # up and left to check neighbors

    for row in range(rows):
        for col in range(cols):
            changed = False
            if 0 < abs(image_colors[row][col] - image_colors[row][col - 1]):
                queue.append((row, col - 1, image_colors[row][col - 1]))
                changed = True
            if 0 < abs(image_colors[row][col] - image_colors[row][col + 1]):
                queue.append((row, col + 1, image_colors[row][col + 1]))
                changed = True
            if 0 < abs(image_colors[row][col] - image_colors[row - 1][col]):
                queue.append((row - 1, col, image_colors[row - 1][col]))
                changed = True
            if 0 < abs(image_colors[row][col] - image_colors[row + 1][col]):
                queue.append((row + 1, col, image_colors[row + 1][col]))
                changed = True
            if not changed:
                continue

            clockwise, counterclockwise = 0, 0
            while queue:
                r, c, color = queue.popleft()
                if c > 0 and abs(image_colors[r][c] - image_colors[r][c - 1]) == 1:
                    counterclockwise += 1
                if c < len(image_colors[0]) - 1 and abs(image_colors[r][c] - image_colors[r][c + 1]) == 1:
                    counterclockwise += 1
                if r > 0 and abs(image_colors[r][c] - image_colors[r - 1][c]) == 1:
                    clockwise += 1
                if r < len(image_colors) - 1 and abs(image_colors[r][c] - image_colors[r + 1][c]) == 1:
                    clockwise += 1
                queue.extendleft([(r + dr, c + dc, color) for dr, dc in directions])
                if clockwise:
                    color = clockwise
                if counterclockwise:
                    color = counterclockwise
            image_colors[row][col] = color

    return len(set(image_colors.rows))

def main():
    t = int(input())
    for _ in range(t):
        n = int(input())
        image_colors = [[int(x) for x in input().split()] for _ in range(n)]
        print(min_operations(image_colors, n))

if __name__ == "__main__":
    main()
