def find_greedy_length(subsegment):
    dp = [0] * (len(subsegment) + 1)
    for i in range(1, len(subsegment)):
        j = 0
        while j < i:
            if subsegment[j] > subsegment[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
            j += 1
    return dp[len(subsegment) - 1]

def longest_greedy_subsequences(arr, k):
    max_length = [0] * (len(arr) - k + 1)
    que = []
    dp = [[0] * k for _ in range(len(arr))]
    for i in range(k, len(arr)):
        # Final element in smallest sequence
        i = i - k + 1
        while que != []:
            j = que.pop(0)
            if arr[j] > dp[i][j % k]:
                dp[i][j % k] = arr[j]  # Set smallest number that is bigger
                ending_index = (i, j % k)  # Get end of current sequence
            if dp[i][j % k] > arr[j]:
                return max_length
            if j < k - 1:
                que.append(j)

        que.append(i)
    return max_length

