def num_caves(n, m):
    mod = 1000000007
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # Only one way to paint a single row

    for i in range(1, n + 1):
        dp[i][0] = 1  # Only one way to paint a single column

        for j in range(1, m + 1):
            if i == 1:
                dp[i][j] = 2 * dp[1][j] - 1  # Picking or not picking the current cell
            else:
                dp[i][j] = 2 * dp[i - 1][j] - dp[i - 2][j]

            dp[i][j] %= mod

            if i > 1:
                for k in range(1, j - 1):
                    if k == 1:
                        dp[i][j] += dp[i - 1][k] * dp[i - 2][j - k]
                    elif k == j - 1:
                        dp[i][j] += dp[i - 1][j - 2] * dp[i - 2][k]
                    else:
                        dp[i][j] += 2 * dp[i - 1][k] * dp[i - 2][j - k]
                    dp[i][j] %= mod

            dp[i][j] -= dp[i - 1][j]
