import sys

def find_min_reversals(s, t):
    n = len(s)
    dp = [float('inf')] * n
    stack = []
    for i in range(n, 0, -1):
        while stack and t[stack[-1]] > s[i-1]:
            dp[i-1] = min(dp[i-1], dp[stack[-1]] + 1)
            stack.pop()
        if stack:
            dp[i-1] = min(dp[i-1], i) - stack[-1] - 1
        if stack and stack[-1] == i-1:
            dp[i-1] = 0
        stack.append(i-1)

    k = float('inf')
    result = []
    stack = []
    current = -1
    for i in range(1, n+1):
        if i in stack:
            continue
        while current != -1 and t[current] < s[i-1]:
            current = stack.pop()
        if current == -1:
            dp[i-1] = 0
        else:
            dp[i-1] = min(dp[i-1], dp[current] + 1)
        if dp[i] < n and t[dp[i]-1] > s[dp[i]]:
            k = min(k, i - dp[i])
            result.append(f"({dp[i]}) {dp[i]-1}")
            dp[i] = current = dp[current]

    if k == float('inf'):
        return -1
    return k, '\n'.join(result)
