def calculate_cave_ways(n, m):
    if n == 1 or m == 1:
        return 0
    mod = 1000000007
    dp = [[0 for _ in range(m)] for _ in range(n)]

    # Fill the first row
    for i in range(1, n):
        dp[i][0] = (dp[i-1][0] + dp[i-1][1]) % mod

    for j in range(1, m):
        dp[1][j] = (dp[1][j-1] + dp[1][j]) % mod

    # Fill the remaining cells
    for i in range(2, n):
        for j in range(1, m):
            dp[i][j] = (dp[i-1][j] + min(dp[i-1][j-1], dp[i-1][j]) + dp[i-1][j+1]) % mod

    ways = 0

    # Possible positions for two black cells
    p1, p2 = [(1, 0), (0, 1), (1, 1), (1, -1)]

    for i in range(n):
        for j in range(m):
            for p in p1:
                for d in range(1, min(i, m)-1, p[0]):
                    w = 0
                    for q in range(d):
                        x, y = j + q * p[0] - d, j + q * p[1]
                        end = j + (min(i, m) - d) * p[0] - d
                        if y < 0 or end < y or y >= p[1]:
                            break
                        v = dp[min(i - y - d, 0)][max(y, 0)] if y <= i and end >= y + d else 0
                        v += dp[max(0, i - y + d)][min(p[1]-d, end-d)]
                        w = (w + v) % mod
                    dp[i][j] = (dp[i][j] + w) % mod
                    if j == m-1:
                        ways = (ways + dp[i][j] * (dp[i][j-1] - dp[i-1][j-1])) % mod
                        ways %= mod

    return ways

