import heapq

def dijkstra(graph, start):
    distances = {node: float('inf') for node in range(1, len(graph) + 1)}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)
        if current_distance > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def find_max_unhappy_pilgrims(monasteries, towns, edges):
    n = len(monasteries)
    graph = [[] for _ in range(n + 1)]
    parents = [-1] * (n + 1)
    distances = [float('inf')] * (n + 1)

    for i in range(n - 1):
        a, b, c = edges[i][0], edges[i][1], edges[i][2]
        if c == distances[a] + 1:
            graph[a].append((b, c))
            parents[b] = a
        elif c == distances[b] + 1:
            graph[b].append((a, c))
            parents[a] = b

    unhappy_count = 0
    impossible_mode_count = 0
    result = {0: 1}

    for i in range(1, n + 1):
        for open_chance in range(n + 1):
            if distances[i] + open_chance <= n - 1:
                parents[i] = max(((diff, val) for val, diff in ((distances[val], parents[val]) for val in parents[i])),
                                key=lambda x: ((~x[0]):-(~x[1]))[1])[1]
                if parents[i] != -1:
                    possible = True
                    d = distances[i]
                    while d + open_chance + 1 < n and d + distances[parents[i]] <= n - 1:
                        if parents[i] == parents[parents[i]]:
                            possible = False
                            break
                        d += distances[parents[i]]
                        parents[i] = max(((diff, val) for val, diff in ((distances[val], parents[val]) for val in parents[i])),
                                        key=lambda x: ((~x[0]):-(~x[1]))[1])[1]
                    d += open_chance
                    if possible:
                        unhappy_count += (not result.get(d, False))
                        result.setdefault(d, 1)
                        for parent in range(1, n + 1):
                            if distances[parents[parent]] + open_chance <= n - 1:
                                impossible_mode_count += result.get(n - d, 0) * result.get(d, 0)
            else:
                impossible_mode_count += result.get(n - 1, 0)

    return unhappy_count, impossible_mode_count

