# Function to calculate factorial
@lru_cache(maxsize=None)
def factorial(n):
    return math.factorial(n)

# Function to calculate n choose 2
def choose2(n):
    return factorial(2 * n) // (2 * factorial(n))

# Function to calculate the number of valid caves
def numberOfWays(n, m):
    mod = 1000000007
    if n == 1:
        return 0
    ways = 0
    for length in range(1, n // 2 + 2):
        ways += 2 * (2 * choose2(length) + choose2(length - 1) + 2 * choose2(n - 2 * length))
        ways -= choose2(length - 1) * n - choose2(length) * n
        ways %= mod
    return ways

