def solve(n, m1, m2, t, xs, ys):
    max_fire_time = 0
    transition_count = 0
    transitions = []
    shot_coordinates = []

    for i in range(m1 + m2):
        max_time_i = math.ceil((n - 1.0) / max(t, t * (ys[i] - ys[i - 1])))
        max_fire_time = max(max_fire_time, max_time_i)
        if i % 2 == 0:
            cur_transition = max(max_time_i + 1, t) * 2
            max_transition = max(max_time_i + 2, t) * 2
        else:
            cur_transition = max_time_i * 2
            max_transition = max(max_time_i + 1, t) * 2
        transition_count += cur_transition
        if cur_transition > m2 - i:
            cur_transition = m2 - i
        if max_transition > m1 + i:
            max_transition = m1 + i
        if i % 2 == 0:
            max_fire_time += 1
        else:
            max_fire_time += 2

        transitions.append([i * 2, i * 2 - 1])
        if max_fire_time < max_transition:
            fire_count = max_fire_time
        else:
            fire_count = max_transition - 1
        shot = [i * 2, 1]
        if i % 2 == 0 and fire_count >= 1:
            shot_coordinates.append([i * 2 - 1, 1])  # 1st lane to 2nd lane
            shot_count += 1
        else:
            shot_coordinates.append([i * 2, 1])
            shot_count += 1
        if i + 1 < len(xs):
            transitions.append([i * 2 + 1, i * 2 + 2])
            shot_coordinates.append([i * 2 + 1, 2])
            shot_count += 1

    if m2 - m1 > 0:
        if max_fire_time * 2 >= transition_count:
            transition_count += m1 + 1 - m2
            transition_count += m2
    else:
        max_fire_time += m1 + 1
        if max_fire_time * 2 >= transition_count:
            transition_count += m1 - m2
            transition_count += m2
        else:
            transition_count = max_fire_time * 2 + 1 - transition_count

    if transition_count > 2000000:
