    return f"Yes\n{m1 + m2}\n{transition_count}\n{' '.join(map(str, e)) for e in shot_coordinates}{" ".join(map(str, transitions[:-1]))}\n{len(shot_coordinates)}\n{' '.join(map(str, shot_coordinates))}"

