def longest_greedy_subsequence(arr: List[int], subsegment_length: int) -> List[int]:
    n = len(arr)
    k = subsegment_length
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    for i in range(1, n + 1):
        dp[1][i] = 1
    for i in range(2, k + 1):
        for j in range(i, n + 1):
            dp[i][j] = 0
            for l in range(1, j):
                if arr[l] < arr[j] and dp[i - 1][l] + 1 > dp[i][j]:
                    dp[i][j] = dp[i - 1][l] + 1
    longest = 0
    for i in range(n - k + 1):
        longest = max(longest, dp[k][i + k])
    return [longest] + [max(dp[i + 1][i + j] for i in range(n - k + 1)) for j in range(k, n + 1 - k)]

