from collections import defaultdict

def findMinFlights(n, m, flights):
    # Build an adjacency list representation of the flights
    graph = defaultdict(list)
    for u, v, d in flights:
        graph[u].append((v, d))

    def dfs(city, prevCity, totalFlights, paths):
        if city == n:
            return totalFlights
        paths.append(city)
        possibleFlights = min(d for u, d in graph[city] if u != prevCity)
        for nextCity, _ in graph[city]:
            if possibleFlights >= _:
                res = dfs(nextCity, city, totalFlights + 1, paths)
                if res != -1:
                    return res + possibleFlights
        paths.pop()
        return -1

    for i, d in flights[0]:
        if d:  # If the first flight is valid
            return dfs(i, -1, 1, [])
    return "Impossible"

