from typing import List

def main():
    # Input
    n, m = map(int, stdin.readline().strip().split())
    flights: List[List[int]] = []
    for _ in range(m):
        line = list(map(int, stdin.readline().strip().split()))
        a, b, d = line[0], line[1], line[2]
        flights.append((a, b, d))

    dp: List[int] = [float('inf')] * (n + 1)
    dp[1] = 0  # Starting point

    for i in range(1, n + 1):
        # Calculate the optimal number of flights from the start to city i
        for a, b, d in flights:
            if a <= i and i <= b:
                dp[i] = min(dp[i], dp[a - 1] + d)

    # Check if it's possible to reach city n
    if dp[n] == float('inf'):
        print("Impossible")
    else:
        print(dp[n])

if __name__ == "__main__":
    main()
