def solve(n, X, p):
    if n == 0:
        return 0.0
    elif n == 1:
        return p[0] - min(X, 1.0 - (sum(p[:1]) - p[0])) * 0.2
    else:
        ideal_buy_cost = 0.2 + solve(n - 1, X, p[:n])[0]
        ideal_buy_total = (X - sum(p)[:n]) * 0.2 + 1.0 - (sum(p)[:n]/n - ideal_buy_cost)
        expected_value = solve(n - 1, X, p[:n])[0] + (X - sum(p)[:n]) * (ideal_buy_total - solve(n - 1, X - sum(p)[:n], p[:n])[0])
        return max(expected_value, ideal_buy_cost + ideal_buy_total)

